import { SYSTEM_ROLES, type SystemRoleKey } from "@/lib/permissions/catalog";
import { sectionsFor, type Guide, type GuideBlock, type GuideSection } from "./content";

/**
 * Renders the in-app guide as Markdown (docs/HOTEL_GUIDE.md, docs/SUPER_ADMIN_GUIDE.md).
 * Generated by `pnpm guide:md`; a unit test fails if the files drift from modules/help/content.ts.
 * Media paths are relative to docs/, so images show on GitHub and in any Markdown viewer.
 */

const LIVE = "https://hotel-qr-code-saas.vercel.app";

const cell = (s: string) => s.replace(/\|/g, "\\|").replace(/\n/g, " ");
const anchor = (s: GuideSection) => s.id;

/** Roles that see this hotel section in the app (same rule as the /help page). */
function rolesFor(section: GuideSection): string {
  if (!section.permissions) return "Everyone";
  const names = (Object.keys(SYSTEM_ROLES) as SystemRoleKey[])
    .filter((k) => sectionsFor([section], (p) => (SYSTEM_ROLES[k].permissions as readonly string[]).includes(p)).length > 0)
    .map((k) => SYSTEM_ROLES[k].name);
  return names.length === Object.keys(SYSTEM_ROLES).length ? "Everyone" : names.join(", ");
}

function block(b: GuideBlock, opts: { links: boolean }): string {
  switch (b.kind) {
    case "p":
      return b.text;
    case "steps":
      return b.items.map((s, i) => `${i + 1}. ${s}`).join("\n");
    case "list":
      return b.items.map((s) => `- ${s}`).join("\n");
    case "table":
      return [`| ${b.head.map(cell).join(" | ")} |`, `| ${b.head.map(() => "---").join(" | ")} |`, ...b.rows.map((r) => `| ${r.map(cell).join(" | ")} |`)].join("\n");
    case "tip":
      return `> **Tip:** ${b.text}`;
    case "warn":
      return `> **Important:** ${b.text}`;
    case "links":
      return opts.links ? `Open in the app: ${b.items.map((l) => `[${l.label}](${LIVE}${l.href})`).join(" · ")}` : "";
    case "media":
      return b.items
        .map((m) =>
          m.type === "image"
            ? `![${m.caption}](../public${m.src})\n*${m.caption}*`
            : `▶ **[${m.caption}](../public${m.src})** (video, no sound)`,
        )
        .join("\n\n");
  }
}

export function guideToMarkdown(guide: Guide, opts: { links?: boolean; roles?: boolean } = {}): string {
  const links = opts.links ?? true;
  const out: string[] = [];
  out.push(`# ${guide.title}`, "");
  out.push(`${guide.intro.replace(/ Use the search box or the contents list\.$/, "")} The same guide is inside the app (${guide.key === "hotel" ? "Help & guide" : "Docs & guide"}).`, "");
  out.push("<!-- Generated from modules/help/content.ts by `pnpm guide:md`. Edit the content there, not here. -->", "");

  out.push("## Where to start", "");
  guide.journey.forEach((j, i) => out.push(`${i + 1}. [${j.title}](#${j.section}) — ${j.text}`));
  out.push("");

  out.push("## Contents", "");
  let group = "";
  for (const s of guide.sections) {
    if (s.group !== group) {
      group = s.group;
      out.push(`- **${group}**`);
    }
    out.push(`  - [${s.title}](#${anchor(s)})`);
  }
  out.push("");

  group = "";
  for (const s of guide.sections) {
    if (s.group !== group) {
      group = s.group;
      out.push("---", "", `## ${group}`, "");
    }
    out.push(`<a id="${anchor(s)}"></a>`, "", `### ${s.title}`, "", `*${s.summary}*`, "");
    if (opts.roles) out.push(`**Shown to:** ${rolesFor(s)}`, "");
    for (const b of s.blocks) {
      const md = block(b, { links });
      if (md) out.push(md, "");
    }
  }
  return out.join("\n").replace(/\n{3,}/g, "\n\n").trimEnd() + "\n";
}
